class Solution {
  public int mirrorFrequency(String s) {
    int[] letters = new int[26], digits = new int[10];
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c >= 'a') letters[c - 'a']++;
      else digits[c - '0']++;
    }
    int total = 0;
    for (int i = 0; i < 13; i++) total += Math.abs(letters[i] - letters[25 - i]);
    for (int i = 0; i < 5; i++) total += Math.abs(digits[i] - digits[9 - i]);
    return total;
  }
}
